{{(() => {
  const en = appsmith.store.bo_lang === 'en';
  const d = GetOrderDetails.data[0] || {};
  const payerBg = { all: 'Получателят плаща всичко', fees: 'Получателят плаща само таксите', nothing: 'Получателят не плаща нищо' };
  const payerEn = { all: 'Recipient pays everything', fees: 'Recipient pays our fees only', nothing: 'Recipient pays nothing' };
  // Divus Foods only (Maria, 2026-11-09): their fees go on the monthly фактура, so the recipient pays the НП
  // alone and all of it goes back to them. Other merchants (TheBasket too) keep the view below unchanged.
  const invoiceView = ['office@divusfoods.com'].includes(String(d.customer_email || '').toLowerCase())
    && !(Number(d.cod_amount) > Number(d.goods_amount));
  if (d.payer === 'all' && invoiceView) return en ? 'Cash on delivery, our fees on your invoice' : 'Наложен платеж, таксите по фактура';
  if (d.payer) return (en ? payerEn : payerBg)[d.payer] || d.payer;
  const bg = { COD: 'Наложен платеж', CARD: 'Платена предварително', Paid: 'Платена предварително' };
  const eng = { COD: 'Cash on delivery', CARD: 'Prepaid', Paid: 'Prepaid' };
  return (en ? eng : bg)[d.payment_method] || d.payment_method || '-';
})()}}
